`timescale 1ns/1ps
package reference_pkg;
import uvm_pkg::*;
`include "uvm_macros.svh"
class native_transaction extends uvm_sequence_item;
  `uvm_object_utils(native_transaction)
  logic [80:0] drive;
  logic [76:0] actual, expected;
  bit sample;
  int unsigned tag;
  function new(string name="native_transaction"); super.new(name); endfunction
endclass
class native_sequence extends uvm_sequence #(native_transaction);
  `uvm_object_utils(native_sequence)
  function new(string name="native_sequence"); super.new(name); endfunction
  task send(logic [80:0] drive, bit sample, int unsigned tag);
    native_transaction item = native_transaction::type_id::create("item");
    start_item(item); item.drive=drive; item.sample=sample; item.tag=tag; finish_item(item);
  endtask

  logic [80:0] pc5_pins;
  virtual native_if pc5_bus;
  task pc5_emit(); send(pc5_pins,1,8); endtask
  task pc5_pulse();
    pc5_pins[80]=0; pc5_emit();
    pc5_pins[80]=1; pc5_emit();
    pc5_pins[80]=0; pc5_emit();
  endtask
  task pc5_ticks(int count);
    repeat(count) begin
      pc5_pins[35]=1; pc5_emit();
      repeat(4) pc5_pulse();
      pc5_pins[35]=0; pc5_emit();
      repeat(4) pc5_pulse();
    end
  endtask
  task pc5_write(logic[7:0] address,logic[31:0] data);
    pc5_pins[78:76]=3'b101;
    pc5_pins[75:68]=address; pc5_pins[67:36]=data;
    pc5_emit(); pc5_pulse();
    pc5_pins[77]=1; pc5_emit(); pc5_pulse();
    pc5_pins[78:76]=0; pc5_emit();
  endtask
  task pc5_width_history();
    int new_width;
    if(!uvm_config_db#(virtual native_if)::get(null,"*","bus",pc5_bus))
      `uvm_fatal("CONFIG","Missing native interface")
    for(int trial=0;trial<6;trial++) begin
      case(trial)
        0:new_width=0; 1:new_width=1; 2:new_width=2;
        3:new_width=4; 4:new_width=64; default:new_width=128;
      endcase
      pc5_pins=0; pc5_emit(); pc5_ticks(4);
      pc5_pins[79]=1; pc5_pins[34]=1; pc5_emit(); pc5_ticks(8);
      pc5_write(4,0); pc5_ticks(8);
      pc5_write(40,64); pc5_ticks(8);
      pc5_write(0,3); pc5_ticks(16);
      if(pc5_bus.exp_wdt_reset!==1)
        `uvm_error("NONVACUITY","Live width update must start inside an aged reset pulse")
      pc5_write(40,new_width);
      if(pc5_bus.exp_wdt_reset!==1)
        `uvm_error("NONVACUITY","APB-only update cannot immediately end watchdog pulse")
      pc5_ticks(4);
      if(new_width<16 && pc5_bus.exp_wdt_reset!==0)
        `uvm_error("NONVACUITY","Consumed smaller width must end the pulse")
      if(new_width>=64 && pc5_bus.exp_wdt_reset!==1)
        `uvm_error("NONVACUITY","Unchanged or increased width must retain the pulse")
      pc5_ticks(140);
      if(pc5_bus.exp_wdt_reset!==0)
        `uvm_error("NONVACUITY","Control pulse must eventually finish")
    end
  endtask

  task body();
    int seed=1;
    void'($value$plusargs("EVENT_SEED=%d", seed));
    send(81'h0,1'b0,7);
    send(81'h0,1'b1,7);
    send(81'h100000000000000000000,1'b1,7);
